<?php
namespace App\Http\Controllers;use App\Models\Booking;use App\Models\Review;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ReviewController extends Controller{public function store(Request $r,Booking $booking){abort_unless($booking->customer_id===auth()->id(),403);abort_unless($booking->status==='completed',422,'Only completed bookings can be reviewed.');if($booking->review)return back()->with('error','Review already submitted.');$data=$r->validate(['rating'=>'required|integer|min:1|max:5','comment'=>'nullable|string|max:1000']);DB::transaction(function()use($booking,$data){Review::create(['booking_id'=>$booking->id,'customer_id'=>auth()->id(),'service_id'=>$booking->service_id]+$data);$avg=Review::where('service_id',$booking->service_id)->avg('rating');$count=Review::where('service_id',$booking->service_id)->count();$booking->service()->update(['rating'=>round($avg,2),'review_count'=>$count]);});return back()->with('success','Thanks for your review!');}}
